{"code":"def transform(grid):
    g=[r[:] for r in grid]
    H=len(g); W=len(g[0])
    pts=[(r,c) for r in range(H) for c in range(W) if g[r][c]==8]
    if not pts: return g
    r0=min(r for r,c in pts); r1=max(r for r,c in pts)
    c0=min(c for r,c in pts); c1=max(c for r,c in pts)
    # A marker on the same row as the top edge, outside left/right, projects to that edge
    for r in range(H):
        for c in range(W):
            v=g[r][c]
            if v==0 or v==8: continue
            if r==r0 and c<c0:
                g[r0][c0]=v
            elif r==r0 and c>c1:
                g[r0][c1]=v
    # A horizontal colored pattern below the object projects onto its bottom edge
    for r in range(r1+1,H):
        cols=[c for c in range(c0,c1+1) if g[r][c] not in (0,8)]
        if cols:
            for c in cols: g[r1][c]=g[r][c]
    return g"}

